/*
 * High-performance portfolio calculations using a C extension.
 *
 * Inputs may be Python lists/tuples of floats or any object exporting a
 * float64 buffer (e.g. NumPy arrays).  The covariance matrix is consumed
 * row by row, so no O(n^2) intermediate copy is ever materialised.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>
#include <string.h>

/* True when a buffer holds native C doubles. */
static int fmt_is_double(const Py_buffer *view)
{
    const char *f = view->format;
    return f == NULL || strcmp(f, "d") == 0 || strcmp(f, "<d") == 0
           || strcmp(f, "=d") == 0 || strcmp(f, "@d") == 0;
}

/* Copy a strided 1-D double buffer into dst. */
static void copy_strided(double *dst, const char *base, Py_ssize_t stride,
                         Py_ssize_t n)
{
    Py_ssize_t i;
    if (stride == (Py_ssize_t)sizeof(double)) {
        memcpy(dst, base, (size_t)n * sizeof(double));
    } else {
        for (i = 0; i < n; i++)
            dst[i] = *(const double *)(base + i * stride);
    }
}

/* Read a 1-D sequence of numbers into a newly allocated array (PyMem_Free). */
static double *vector_from_object(PyObject *obj, Py_ssize_t *n_out)
{
    Py_buffer view;
    PyObject *fast, **items;
    double *buf;
    Py_ssize_t n, i;

    if (PyObject_CheckBuffer(obj)
        && PyObject_GetBuffer(obj, &view, PyBUF_STRIDES | PyBUF_FORMAT) == 0) {
        if (view.ndim == 1 && view.itemsize == (Py_ssize_t)sizeof(double)
            && fmt_is_double(&view)) {
            n = view.shape[0];
            buf = (double *)PyMem_Malloc((size_t)(n > 0 ? n : 1) * sizeof(double));
            if (buf == NULL) {
                PyBuffer_Release(&view);
                return (double *)PyErr_NoMemory();
            }
            copy_strided(buf, (const char *)view.buf,
                         view.strides ? view.strides[0]
                                      : (Py_ssize_t)sizeof(double), n);
            PyBuffer_Release(&view);
            *n_out = n;
            return buf;
        }
        PyBuffer_Release(&view);
    }
    PyErr_Clear();

    fast = PySequence_Fast(obj, "expected a sequence of numbers");
    if (fast == NULL)
        return NULL;
    n = PySequence_Fast_GET_SIZE(fast);
    items = PySequence_Fast_ITEMS(fast);
    buf = (double *)PyMem_Malloc((size_t)(n > 0 ? n : 1) * sizeof(double));
    if (buf == NULL) {
        Py_DECREF(fast);
        return (double *)PyErr_NoMemory();
    }
    for (i = 0; i < n; i++) {
        PyObject *it = items[i];
        if (PyFloat_CheckExact(it)) {
            buf[i] = PyFloat_AS_DOUBLE(it);
        } else {
            double v = PyFloat_AsDouble(it);
            if (v == -1.0 && PyErr_Occurred()) {
                PyMem_Free(buf);
                Py_DECREF(fast);
                return NULL;
            }
            buf[i] = v;
        }
    }
    Py_DECREF(fast);
    *n_out = n;
    return buf;
}

/* dot product, sequential accumulation (matches the Python baseline order) */
static double dot(const double *a, const double *b, Py_ssize_t n)
{
    double s = 0.0;
    Py_ssize_t i;
    for (i = 0; i < n; i++)
        s += a[i] * b[i];
    return s;
}

/* temp[i] = sum_j cov[i][j] * w[j] ; returns 0 on success, -1 on error. */
static int cov_matvec(PyObject *cov, const double *w, Py_ssize_t n, double *temp)
{
    Py_buffer view;
    PyObject *rows, **row_items;
    Py_ssize_t i, j, nrows;

    /* Fast path: a single 2-D float64 buffer (NumPy matrix). */
    if (PyObject_CheckBuffer(cov)
        && PyObject_GetBuffer(cov, &view, PyBUF_STRIDES | PyBUF_FORMAT) == 0) {
        if (view.ndim == 2 && view.itemsize == (Py_ssize_t)sizeof(double)
            && fmt_is_double(&view)) {
            const char *base = (const char *)view.buf;
            Py_ssize_t rs, cs;
            if (view.shape[0] != n || view.shape[1] != n) {
                PyBuffer_Release(&view);
                PyErr_SetString(PyExc_ValueError,
                                "covariance matrix shape does not match weights");
                return -1;
            }
            rs = view.strides ? view.strides[0]
                              : (Py_ssize_t)(n * sizeof(double));
            cs = view.strides ? view.strides[1] : (Py_ssize_t)sizeof(double);
            if (cs == (Py_ssize_t)sizeof(double)) {
                for (i = 0; i < n; i++)
                    temp[i] = dot((const double *)(base + i * rs), w, n);
            } else {
                for (i = 0; i < n; i++) {
                    const char *row = base + i * rs;
                    double s = 0.0;
                    for (j = 0; j < n; j++)
                        s += (*(const double *)(row + j * cs)) * w[j];
                    temp[i] = s;
                }
            }
            PyBuffer_Release(&view);
            return 0;
        }
        PyBuffer_Release(&view);
    }
    PyErr_Clear();

    /* General path: sequence of rows (list of lists, list of arrays, ...). */
    rows = PySequence_Fast(cov, "covariance matrix must be a sequence of rows");
    if (rows == NULL)
        return -1;
    nrows = PySequence_Fast_GET_SIZE(rows);
    if (nrows != n) {
        Py_DECREF(rows);
        PyErr_SetString(PyExc_ValueError,
                        "covariance matrix shape does not match weights");
        return -1;
    }
    row_items = PySequence_Fast_ITEMS(rows);

    for (i = 0; i < n; i++) {
        PyObject *row = row_items[i];
        double s = 0.0;

        if (PyList_CheckExact(row) || PyTuple_CheckExact(row)) {
            PyObject **cells;
            Py_ssize_t len;
            if (PyList_CheckExact(row)) {
                len = PyList_GET_SIZE(row);
                cells = ((PyListObject *)row)->ob_item;
            } else {
                len = PyTuple_GET_SIZE(row);
                cells = ((PyTupleObject *)row)->ob_item;
            }
            if (len != n)
                goto shape_error;
            for (j = 0; j < n; j++) {
                PyObject *c = cells[j];
                if (PyFloat_CheckExact(c)) {
                    s += PyFloat_AS_DOUBLE(c) * w[j];
                } else {
                    double v = PyFloat_AsDouble(c);
                    if (v == -1.0 && PyErr_Occurred())
                        goto error;
                    s += v * w[j];
                }
            }
        } else {
            Py_ssize_t len = 0;
            double *rowbuf = vector_from_object(row, &len);
            if (rowbuf == NULL)
                goto error;
            if (len != n) {
                PyMem_Free(rowbuf);
                goto shape_error;
            }
            s = dot(rowbuf, w, n);
            PyMem_Free(rowbuf);
        }
        temp[i] = s;
    }
    Py_DECREF(rows);
    return 0;

shape_error:
    PyErr_SetString(PyExc_ValueError,
                    "covariance matrix rows must all have len(weights) entries");
error:
    Py_DECREF(rows);
    return -1;
}

static PyObject *portfolio_risk_c(PyObject *self, PyObject *args)
{
    PyObject *weights_obj, *cov_obj;
    double *w = NULL, *temp = NULL;
    Py_ssize_t n = 0;
    double risk_squared;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    w = vector_from_object(weights_obj, &n);
    if (w == NULL)
        return NULL;

    temp = (double *)PyMem_Malloc((size_t)(n > 0 ? n : 1) * sizeof(double));
    if (temp == NULL) {
        PyMem_Free(w);
        return PyErr_NoMemory();
    }

    if (cov_matvec(cov_obj, w, n, temp) != 0) {
        PyMem_Free(temp);
        PyMem_Free(w);
        return NULL;
    }

    risk_squared = dot(w, temp, n);
    PyMem_Free(temp);
    PyMem_Free(w);

    if (risk_squared < 0.0)
        risk_squared = 0.0;
    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject *portfolio_return_c(PyObject *self, PyObject *args)
{
    PyObject *weights_obj, *returns_obj;
    double *w = NULL, *r = NULL;
    Py_ssize_t n = 0, m = 0;
    double total;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &returns_obj))
        return NULL;

    w = vector_from_object(weights_obj, &n);
    if (w == NULL)
        return NULL;
    r = vector_from_object(returns_obj, &m);
    if (r == NULL) {
        PyMem_Free(w);
        return NULL;
    }
    if (m < n) {
        PyMem_Free(r);
        PyMem_Free(w);
        PyErr_SetString(PyExc_ValueError,
                        "expected_returns is shorter than weights");
        return NULL;
    }

    total = dot(w, r, n);
    PyMem_Free(r);
    PyMem_Free(w);
    return PyFloat_FromDouble(total);
}

